<?php
$uid = (int)$u['id']; $admin = $u['role'] === 'admin'; $id = (int)($_GET['id'] ?? 0);
handle('ev_add', function () use ($uid, $id) { Disputes::evidence($uid, $id, (string)$_POST['note']); return 'Evidence note added.'; });
handle('d_decide', function () use ($uid, $admin, $id) { if (!$admin) throw new AppError('Only administrators can decide disputes.'); Disputes::decide($uid, $id, (string)$_POST['resolution'], (string)($_POST['note'] ?? '')); return 'Decision recorded.'; });
$base = 'SELECT d.*, e.buyer_id, e.seller_id, t.from_wallet_id, t.to_wallet_id, u.name raiser FROM disputes d LEFT JOIN escrow_milestones m ON m.id=d.milestone_id LEFT JOIN escrows e ON e.id=m.escrow_id LEFT JOIN transactions t ON t.id=d.txn_id JOIN users u ON u.id=d.raised_by';
if ($id) {
  $d = row("$base WHERE d.id=?", [$id]);
  if (!$d || (!$admin && !Disputes::canSee($uid, $d))) { http_response_code(404); echo card('', empty_state('Dispute not found.')); return; }
  $ev = rows('SELECT v.*, u.name FROM dispute_evidence v JOIN users u ON u.id=v.user_id WHERE v.dispute_id=? ORDER BY v.id', [$id]); $tl = rows("SELECT x.*, u.name FROM timeline_events x LEFT JOIN users u ON u.id=x.actor_id WHERE entity_type='dispute' AND entity_id=? ORDER BY x.id", [$id]); $open = in_array($d['status'], ['open', 'under_review'], true);
  $evh = ''; foreach ($ev as $v) $evh .= '<div style="padding:8px 0;border-top:1px solid var(--line)"><strong>' . e($v['name']) . '</strong> <span class="hint">' . e(fdate($v['created_at'])) . '</span><div>' . e($v['note']) . '</div></div>';
  $tls = '<ul class="timeline">'; foreach ($tl as $x) $tls .= '<li><strong>' . e(str_replace('_', ' ', ucfirst($x['event']))) . '</strong> <span class="hint">' . e($x['name'] ?? 'System') . ' &middot; ' . e(fdate($x['created_at'])) . '</span><div class="hint">' . e($x['note']) . '</div></li>'; $tls .= '</ul>';
  $about = $d['txn_id'] ? 'Transaction ' . ref_link((string)val('SELECT ref FROM transactions WHERE id=?', [$d['txn_id']])) : 'Escrow milestone #' . (int)$d['milestone_id'];
  $dec = $admin && $open ? card('Administrator decision', form_start('d_decide') . select('Decision', 'resolution', ['review' => 'Mark under review', 'refund' => 'Refund (return funds to payer/buyer)', 'release' => 'Release (escrow only: pay seller)', 'reject' => 'Reject dispute'], 'review') . field('Decision note', 'note', 'text', '', 'maxlength="255"') . btn('Record decision') . '</form><p class="hint">Refunds are posted as ledger reversals and are blocked if the transaction was already refunded.</p>') : '';
  echo page_head('Dispute ' . $d['ref'], 'Raised by ' . $d['raiser'] . ' &middot; ' . fdate($d['created_at']), badge($d['status']) . ' <a class="btn secondary sm" href="' . e(url($admin ? 'admin' : 'disputes', $admin ? ['tab' => 'disputes'] : [])) . '">' . e(t('Back')) . '</a>') . '<div class="grid g2"><div class="grid">' . card('Summary', '<dl class="kv"><dt>About</dt><dd>' . $about . '</dd><dt>Reason</dt><dd style="font-weight:400">' . e($d['reason']) . '</dd><dt>Resolution</dt><dd>' . e(ucfirst($d['resolution'])) . '</dd><dt>Decision note</dt><dd style="font-weight:400">' . e($d['decision_note'] ?: '-') . '</dd></dl>') . card('Evidence notes', ($evh ?: '<p class="muted">No evidence yet.</p>') . ($open ? form_start('ev_add') . '<div class="field" style="margin-top:12px"><label for="note">Add a note</label><textarea id="note" name="note" rows="3" required maxlength="400"></textarea></div>' . btn('Add evidence', 'secondary sm') . '</form>' : '')) . '</div><div class="grid">' . $dec . card('Status timeline', $tls) . '</div></div>'; return;
}
$list = rows($base . ($admin ? '' : ' WHERE d.raised_by=? OR e.buyer_id=? OR e.seller_id=? OR t.from_wallet_id IN (SELECT id FROM wallets WHERE user_id=?) OR t.to_wallet_id IN (SELECT id FROM wallets WHERE user_id=?)') . ' ORDER BY d.id DESC LIMIT 50', $admin ? [] : [$uid, $uid, $uid, $uid, $uid]); $rows = [];
foreach ($list as $d) $rows[] = ['<a href="' . e(url('disputes', ['id' => $d['id']])) . '"><strong>' . e($d['ref']) . '</strong></a>', e(mb_substr($d['reason'], 0, 70)), e($d['raiser']), e(fdate($d['created_at'], false)), badge($d['status'])];
echo page_head('Disputes', 'Support tracking for transactions and escrow milestones. Open a dispute from a receipt or an escrow milestone.') . card('', tbl(['Reference', 'Reason', 'Raised by', 'Date', 'Status'], $rows, 'No disputes. If a payment goes wrong, open one from its receipt.'));
